//! Worlds generated by a script.
//!
//! Some worlds are not edited with the property tree: a script writes them,
//! because they are repetitive in a way a form does not cover --- a swerve is
//! four modules identical except for their corner, with their inertias
//! computed, and `worlds/gen_swerve.py` generates them together with the robot
//! map so the ORDER of the actuators cannot diverge.
//!
//! That used to mean changing an option of such a world was opening the .py
//! or the terminal. A self-respecting generator DECLARES what can be changed,
//! with `--options`, and the app draws the panel for it: a new option shows up
//! in the window on its own the day someone adds it to the script, and there
//! is no list of options in Rust silently going stale.
//!
//! # The contract
//!
//! `gen_<name>.py --options` prints, and nothing else, a JSON object:
//!
//! ```text
//! { "file": "swerve",
//!   "generates": ["worlds/swerve.sdf", ...],
//!   "options": [ { "name", "label", "type": "int" | "bool" | "choice",
//!                  "default", "help"?, "min"?, "max"?, "unit"?,
//!                  "choices"?: [[value, label], ...] } ] }
//! ```
//!
//! and `gen_<name>.py --set name=value [--set ...]` regenerates the world.

use std::path::Path;

use anyhow::{bail, Context, Result};

use super::paths::resolve;

/// The script that generates a world, if there is one: `worlds/gen_<name>.py`.
///
/// It is a naming CONVENTION, not a registry: a new generator is named like
/// that and shows up in the app without touching anything here.
pub fn generator_for(sim_dir: &Path, rel: &str) -> Option<String> {
    let sdf = resolve(sim_dir, rel).ok()?;
    let name = sdf.file_stem()?.to_str()?;
    let script = sdf.with_file_name(format!("gen_{name}.py"));
    script
        .is_file()
        .then(|| format!("worlds/gen_{name}.py"))
}

fn run_generator(sim_dir: &Path, python: &Path, script: &str, args: &[String]) -> Result<String> {
    let path = resolve(sim_dir, script)?;
    let mut cmd = std::process::Command::new(python);
    cmd.arg(&path)
        .args(args)
        // The script writes paths relative to `sim/` and resolves the field
        // from there: launching it from somewhere else changes the world under
        // its feet.
        .current_dir(sim_dir);
    #[cfg(windows)]
    {
        // Without this, a black console flashes every time the window opens
        // the options panel. The app is GUI and the script is console.
        use std::os::windows::process::CommandExt;
        cmd.creation_flags(0x0800_0000); // CREATE_NO_WINDOW
    }
    let output = cmd
        .output()
        .with_context(|| format!("could not run {} {}", python.display(), script))?;
    if !output.status.success() {
        // The script's stderr is the only thing that explains a failure of
        // its own, and without this the UI would show "exit code 1" and
        // nothing more.
        bail!(
            "{script} failed:\n{}",
            String::from_utf8_lossy(&output.stderr).trim()
        );
    }
    Ok(String::from_utf8_lossy(&output.stdout).into_owned())
}

/// What this world's generator declares can be changed.
///
/// `None` if the world has no generator. The JSON is defined by the script;
/// it is not interpreted here, it is passed to the UI as is.
pub fn generator_options(
    sim_dir: &Path,
    python: &Path,
    rel: &str,
) -> Result<Option<serde_json::Value>> {
    let Some(script) = generator_for(sim_dir, rel) else {
        return Ok(None);
    };
    let output = run_generator(sim_dir, python, &script, &["--options".into()])?;
    let mut manifest: serde_json::Value = serde_json::from_str(output.trim())
        .with_context(|| format!("{script} --options did not return JSON:\n{output}"))?;
    if let Some(obj) = manifest.as_object_mut() {
        obj.insert("script".into(), serde_json::Value::String(script));
    }
    Ok(Some(manifest))
}

/// Regenerates the world with these values. Returns what the script printed.
pub fn generate_world(
    sim_dir: &Path,
    python: &Path,
    rel: &str,
    values: &serde_json::Value,
) -> Result<String> {
    let script = generator_for(sim_dir, rel)
        .ok_or_else(|| anyhow::anyhow!("{rel} has no generator"))?;
    let mut args = Vec::new();
    for (key, value) in values.as_object().into_iter().flatten() {
        // A `=` or a newline inside the value would split the pair in two,
        // and the script would receive a key that does not exist.
        let text = match value {
            serde_json::Value::String(s) => s.clone(),
            other => other.to_string(),
        };
        if key.contains('=') || text.contains('=') || text.contains('\n') {
            bail!("invalid value for {key}: {text:?}");
        }
        args.push("--set".into());
        args.push(format!("{key}={text}"));
    }
    run_generator(sim_dir, python, &script, &args)
}

#[cfg(test)]
mod tests {
    use std::path::PathBuf;

    use super::*;

    /// The generator is found BY NAME, and that is all the registration there
    /// is: `gen_<world>.py` next to the `.sdf`. If this breaks, generated
    /// worlds lose their options panel in the app and there is no error.
    #[test]
    fn the_generator_is_found_by_convention() {
        let root = std::env::temp_dir().join("mars-studio-test-generator");
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(root.join("worlds")).unwrap();
        std::fs::write(root.join("worlds/swerve.sdf"), "<sdf/>").unwrap();
        std::fs::write(root.join("worlds/gen_swerve.py"), "# hi").unwrap();
        std::fs::write(root.join("worlds/by-hand.sdf"), "<sdf/>").unwrap();

        assert_eq!(
            generator_for(&root, "worlds/swerve.sdf").as_deref(),
            Some("worlds/gen_swerve.py")
        );
        assert_eq!(generator_for(&root, "worlds/by-hand.sdf"), None);
        assert_eq!(generator_for(&root, "worlds/missing.sdf"), None);
        let _ = std::fs::remove_dir_all(&root);
    }

    /// The contract with the generator, end to end.
    ///
    /// If this fails, the app's options panel comes out empty and there is no
    /// error: `--options` is an agreement between a Python script and a
    /// JavaScript panel, and nothing else checks it. It skips itself if the
    /// conda environment is missing, because it is the only python the
    /// scripts can use.
    #[test]
    fn the_generator_declares_its_options() {
        let sim = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();
        let Some(python) = ["USERPROFILE", "LOCALAPPDATA"]
            .iter()
            .filter_map(|v| std::env::var(v).ok())
            .map(|r| PathBuf::from(r).join("miniforge3/envs/mars-sim/python.exe"))
            .find(|p| p.is_file())
        else {
            eprintln!("no mars-sim environment: skipped");
            return;
        };

        let manifest = generator_options(sim, &python, "worlds/swerve.sdf")
            .expect("the generator did not answer")
            .expect("worlds/swerve.sdf has a generator and it was not found");
        let options = manifest["options"].as_array().expect("no options");
        assert!(options.len() >= 3, "{manifest}");
        for o in options {
            // What the UI needs from each one to be able to draw a control.
            assert!(o["name"].is_string(), "{o}");
            assert!(o["default"] != serde_json::Value::Null, "{o}");
            let kind = o["type"].as_str().unwrap_or("");
            assert!(matches!(kind, "bool" | "int" | "choice"), "type {kind}");
            if kind == "choice" {
                let list = o["choices"].as_array().expect("choice without a list");
                assert!(list.iter().all(|p| p[0].is_string()), "{o}");
            }
        }
    }
}
